=== FILE: prefix_validator.py ===
"""Topic path subscription matcher."""
def is_topic_subscribed(subscribed_pattern: str, event_topic: str) -> bool:
    if subscribed_pattern == event_topic:
        return True
    # If the event topic starts with the subscribed pattern,
    # the character immediately following the pattern in the event topic
    # must be a topic segment separator '::' to prevent partial matches
    # like 'orders' matching 'orders_admin'.
    if event_topic.startswith(subscribed_pattern):
        # Check if the next characters form a segment separator
        # This handles cases like 'orders' matching 'orders::created'
        # but not 'orders_admin::created'.
        return event_topic[len(subscribed_pattern):].startswith("::")
    return False

def clean_topic_segment(topic: str) -> str:
    return topic.strip().lower()

def is_wildcard_subscription(pattern: str) -> bool:
    return pattern.strip() in ("*", "**")
